<script setup lang="ts">
import type { SiteAnalysis } from "~/shared/types/analysis";
const router = useRouter(); const { $api } = useNuxtApp(); const loading = ref(false); const error = ref("");
interface UsageSummary { dailyUsed: number; dailyLimit: number; active: number; concurrentLimit: number }
const { data } = await useFetch<{ items: SiteAnalysis[]; usage: UsageSummary | null }>("/api/dashboard", { $fetch: $api, default: () => ({ items: [], usage: null }) });
const usage = computed(() => data.value.usage);
async function start(payload: { url: string; options: Record<string, unknown> }) { loading.value=true; error.value=""; try { const result=await $api<{analysisId:string}>("/api/analyses",{method:"POST",body:payload}); await router.push(`/analyses/${result.analysisId}`); } catch(cause:any){ error.value=cause?.data?.statusMessage||cause?.data?.data?.message||cause?.message||"분석 요청에 실패했습니다."; } finally{loading.value=false;} }
function label(status:string){return status==="completed"?"완료":status==="partially_completed"?"부분 완료":status==="failed"?"실패":"진행 중"}
</script>
<template><div><section class="hero"><div><p class="eyebrow">URL 기반 AI QA</p><h1>URL을 넣으면,<br>실행기가 검증합니다.</h1><p class="lead">Vercel은 빠른 요청과 결과 화면만 담당합니다. 격리된 GitHub Actions 실행기가 Chromium으로 화면을 수집하고 AI 분석과 읽기 전용 테스트를 수행한 뒤, 비공개 Supabase 저장소에 근거를 남깁니다.</p><div v-if="usage" class="notice">오늘 {{ usage.dailyUsed }}/{{ usage.dailyLimit }}회 사용 · 현재 실행 {{ usage.active }}/{{ usage.concurrentLimit }} · 최대 5페이지, 깊이 2</div></div><UrlAnalysisForm :loading="loading" @submit="start" /></section><div v-if="error" class="error-box" role="alert">{{ error }}</div><section class="section"><div class="section-head"><div><h2>최근 분석</h2><p>대기, 실행, 완료 상태는 Supabase를 기준으로 표시됩니다.</p></div><NuxtLink to="/analyses">전체 보기 →</NuxtLink></div><div v-if="!data.items.length" class="empty">아직 분석 기록이 없습니다.</div><div v-else class="card"><NuxtLink v-for="item in data.items.slice(0,5)" :key="item.id" class="analysis-row" :to="`/analyses/${item.id}`"><div><div class="analysis-row__url">{{ item.normalizedUrl }}</div><div class="analysis-row__meta"><span>{{ new Date(item.createdAt).toLocaleString('ko-KR') }}</span><span>{{ item.currentMessage }}</span></div></div><span class="tag" :class="`tag--${item.status==='completed'?'success':item.status==='failed'?'failed':'warning'}`">{{ label(item.status) }}</span></NuxtLink></div></section><section class="section"><div class="grid grid--3"><div class="card panel"><strong>Vercel 웹 앱</strong><p class="muted">로그인, 입력 검증, 작업 생성과 결과 조회만 담당합니다.</p></div><div class="card panel"><strong>GitHub Actions</strong><p class="muted">Chromium, 크롤링, AI 분석, 자동 테스트를 최대 10분 동안 실행합니다.</p></div><div class="card panel"><strong>Supabase</strong><p class="muted">RLS가 적용된 데이터와 비공개 스크린샷을 사용자별로 보관합니다.</p></div></div></section></div></template>
